+pub(crate) fn compacted_segment_has_uncommitted_tail(
+    dir: &Path,
+    manifest: &SegmentManifest,
+) -> std::io::Result<bool> {
+    PageOutput::inspect(dir, manifest).map(|(_, tail)| tail)
+}
